class Solution {
    public int findTargetSumWays(int[] nums, int target) {
        int sum = 0;
        for (int x : nums) sum += x;
        if (Math.abs(target) > sum || (sum + target) % 2 != 0) return 0;
        int subset = (sum + target) / 2;
        int[] dp = new int[subset + 1];
        dp[0] = 1;
        for (int x : nums) {
            for (int j = subset; j >= x; j--) {
                dp[j] += dp[j - x];
            }
        }
        return dp[subset];
    }
}
